import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.TQKaXlFR.js";const m=JSON.parse('{"title":"安全部署与权限边界","description":"","frontmatter":{},"headers":[],"relativePath":"operations/security.md","filePath":"operations/security.md"}'),d={name:"operations/security.md"};function c(i,e,n,s,p,l){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="安全部署与权限边界" tabindex="-1">安全部署与权限边界 <a class="header-anchor" href="#安全部署与权限边界" aria-label="Permalink to &quot;安全部署与权限边界&quot;">​</a></h1><p>本页用于部署者和开发者核对当前实现的真实安全边界，不替代组织自己的审计、数据分级或生产安全方案。前提是完成初始化账号处理、版本配对和<a href="./../guide/configuration.html">配置</a>。</p><h2 id="密钥与凭据" tabindex="-1">密钥与凭据 <a class="header-anchor" href="#密钥与凭据" aria-label="Permalink to &quot;密钥与凭据&quot;">​</a></h2><p><code>JWT_SECRET</code>从服务端环境读取，至少32个UTF-8字节，缺失/过短拒绝启动。不要将服务端密钥放进VITE变量、URL、浏览器存储配置或公开示例。JWT本身是登录凭证，请求头采用原始token，反代与访问日志应脱敏。</p><p><code>CONFIG_MASTER_KEY</code>是Base64的32字节AES-GCM主密钥，业务配置和模型DB凭据按purpose绑定加密。读取接口显示是否配置/来源/运行状态，不能返回密钥明文；“保留、替换、清除”必须有明确操作。主密钥必须稳定并受控备份，当前没有自动轮换重加密工具。</p><p>前端<code>VITE_APP_STORE_SECURE_KEY</code>可见于产物，只用于前端持久化处理，不是服务端授权根。生产默认<code>/api</code>，不向上游mock发送真实凭据。初始化种子密码和演示账号处理见<a href="./../guide/first-login.html">首次登录</a>。</p><h2 id="平台、操作码与资源范围" tabindex="-1">平台、操作码与资源范围 <a class="header-anchor" href="#平台、操作码与资源范围" aria-label="Permalink to &quot;平台、操作码与资源范围&quot;">​</a></h2><p>Controller的<code>@PreAuthorize</code>及服务端身份校验是实际授权依据。平台接口通常要求 <code>@platformAccess.isPlatformIdentity()</code> 与操作码同时满足；前端按钮/菜单隐藏用于用户体验，不能代替服务验权。</p><table tabindex="0"><thead><tr><th>资源</th><th>当前额外边界</th></tr></thead><tbody><tr><td>本人资料</td><td>服务端获取当前userId，不允许通过请求选择他人</td></tr><tr><td>本人通知</td><td>当前数据库用户有效，recipient_user_id与tenant匹配；批量先整体验权</td></tr><tr><td>文件</td><td>当前创建者，启用租户后还匹配tenant；所有下载/详情/删除均验权</td></tr><tr><td>低代码表单</td><td>平台身份+操作码管理；不能匿名公开填写</td></tr><tr><td>低代码记录</td><td>formId+tenant过滤、操作码；creator由认证主体写入，查询不统一仅本人</td></tr><tr><td>AI场景</td><td>注册app对应业务权限、服务端主体/资源校验、明确context字段</td></tr></tbody></table><p>默认 <code>tenant.enable=false</code>，启用前核对既有数据、默认租户和每条业务路径。MyBatis租户拦截器排除了全局菜单/租户及部分关联表；不能宣传“开关一开所有表自动隔离”。准确模式见<a href="./../development/tenant-platform.html">租户与平台</a>。</p><h2 id="外部服务与上传" tabindex="-1">外部服务与上传 <a class="header-anchor" href="#外部服务与上传" aria-label="Permalink to &quot;外部服务与上传&quot;">​</a></h2><p>邮件、OSS、Druid默认关闭。开启Druid配置不意味着能访问监控控制台，当前Security明确拒绝<code>/druid/**</code>；不要为排障简单加入匿名allowlist。外部服务启用需完整私有配置和单独验证。</p><p>OSS上传最大20MiB、扩展名白名单、记录落库/对象失败补偿；这不包含病毒扫描、完整文件格式鉴定或匿名对象访问安全承诺。bucket访问策略、外链有效期、网络ACL和扫描由部署方案补齐；不要把所有bucket设公开来绕过下载问题。</p><p>用户导入单文件5MiB、解压尺寸/行数/请求长度限制，与通用文件上传不同。场景读取限制16KiB JSON、禁止请求伪造身份/表达式/SQL/URL，返回no-store和traceId。供应商测试目标、重定向和返回值有受控边界，仍需审查部署代理与出站策略。</p><h2 id="日志与公开文档" tabindex="-1">日志与公开文档 <a class="header-anchor" href="#日志与公开文档" aria-label="Permalink to &quot;日志与公开文档&quot;">​</a></h2><p>日志可用于诊断，但不能记录密码、JWT、验证码、配置密钥、真实手机号、批量数据全文或AI prompt/context。数据库异常向客户端返回短提示；供应商错误按outcome/状态和可用trace定位，不公开完整请求响应。</p><p>公开文档不发布任务板、QA记录、临时账号、DPAPI或本机个人目录。敏感漏洞通过项目实际配置的私有联系渠道报告；没有配置渠道时不要虚构邮箱，也不要在公开issue贴可利用凭据。许可与历史公开是独立关口，本机门槛通过不等于授权公开整个Git历史。</p><h2 id="可验证结果与失败恢复" tabindex="-1">可验证结果与失败恢复 <a class="header-anchor" href="#可验证结果与失败恢复" aria-label="Permalink to &quot;可验证结果与失败恢复&quot;">​</a></h2><p>用无token请求应得到401；有会话但无管理权限仍被拒；跨owner/tenant操作不成功；配置读取不含明文；失效revision保留输入并失败。发现边界不符时记录最小脱敏复现，停止依赖该失败链路的操作，按<a href="./../contributing/contribution.html">贡献流程</a>提交实际修复与测试，不降低规则掩盖。</p><p>源码：<code>system-framework/src/main/java/com/xinghuiTec/config/SecurityConfig.java</code>、<code>JwtSigningKeyConfiguration.java</code>、<code>common/common-core/src/main/java/com/xinghuiTec/config/SecretCipher.java</code>、<code>common/common-tenant/src/main/java/com/xinghuiTec/config/tenant/</code>；<code>system-admin/src/main/java/com/xinghuiTec/</code>下的<code>controller/</code>、<code>lowcode/LowcodeIdentity.java</code>、<code>ai/prompt/AiSceneReadService.java</code>、<code>config/UserImportUploadLimitFilter.java</code>；前端<code>apps/web-ele/src/api/request.ts</code>及对应权限/会话测试。</p>',20)])])}const u=t(d,[["render",c]]);export{m as __pageData,u as default};
